/* The NeXTSTEP kit: everything the interface is built from.
 *
 * Generated by design/build.py from design/kit/. Do not edit by hand.
 *
 * Each part is one source in design/kit/, holding its element and its
 * styles together:
 *
 *   base                        the tokens, the reset and the two edges
 *   desk                        what the desk remembers, and the gestures
 *   nx-window                   a frame that drags, resizes, closes and remembers
 *   nx-menu, nx-menu-item       the menu, and the entries that open windows
 *   nx-popup                    a button that brings up a list of choices while it is held
 *   nx-dock, nx-tile, nx-floor  the column of tiles a person arranges, and the floor the others stand on
 *   nx-scroller                 a view with NeXT's scroller on its left
 *   nx-shelf, nx-thing          a floor of icons, one of which may be chosen
 *   nx-ask                      the panel that asks before a change
 *   nx-viewer                   the File Viewer, as four bands in one window
 *   panel                       nx-portrait, nx-row and nx-field, for an info panel
 *   nx-slider                   a knob in a trough, moving between the steps it is given
 *   nx-leds                     a row of lamps lighting from the left, for a share of something
 *   terminal                    a text view, black on white
 *
 * They use the light DOM rather than a shadow root, so the stylesheet
 * reaches them and the design tokens carry through.
 */

const SVG_NS = "http://www.w3.org/2000/svg";
const STORE = "nextstep-workspace:v4";

/* --- what the desk remembers -------------------------------------------- */

/**
 * What the desk keeps about one element, under that element's name. Each
 * element writes the keys it uses and reads them back, so every key may be
 * missing.
 * @typedef {object} Remembered
 * @property {boolean} [open] - A window: whether it is open.
 * @property {number} [x] - A window or the menu: its left edge.
 * @property {number} [y] - A window or the menu: its top edge.
 * @property {number} [w] - A window: its width.
 * @property {number} [h] - A window: its height.
 * @property {string} [front] - The desk: the name of the window in front, or
 *   "" where the desk itself is.
 * @property {Record<string, number>} [places] - The dock: which slot each tile
 *   stands in, by the tile's name.
 */

/** @returns {Record<string, Remembered>} Everything saved about the desk, or
 *  an empty record. */
function readState() {
  try { return JSON.parse(localStorage.getItem(STORE) ?? "{}") ?? {}; }
  catch { return {}; }
}

/**
 * Writes one element's state, leaving every other one untouched.
 * @param {string} name - What the element calls itself.
 * @param {Remembered} state - The keys to merge in.
 */
function remember(name, state) {
  const all = readState();
  all[name] = { ...(all[name] ?? {}), ...state };
  localStorage.setItem(STORE, JSON.stringify(all));
}

/** @param {string} name @returns {Remembered} That element's saved state. */
function recall(name) {
  return readState()[name] ?? {};
}

/* --- how large the desk is drawn -----------------------------------------

   Everything here is measured off NeXTSTEP at its own 1120 by 832: a tile is
   68, a menu row is 20, the type is 12. On the screen that machine had, that
   is what those things were. On a 32 inch panel it is small, and the answer is
   to draw the same desk larger rather than to pick new numbers, which would
   be a second set of measurements and the end of every one of them being the
   original's.

   CSS zoom, because it is the one thing that scales a layout rather than a
   picture of one: the pointer lands where it looks, a window measures what it
   is, and the dock stays against the edge. Any multiplier is allowed. The
   icons are bitmaps, so a step that is neither whole nor half draws their
   pixels across fractions of a screen pixel, and that is accepted here.
   Which steps are offered is the interface's to say, in app/size.js. */

/** How large the desk is drawn, as a multiplier. */
function deskScale() {
  return Number(getComputedStyle(document.body).zoom) || 1;
}

/**
 * Draws the desk at that size.
 * @param {number} scale - A multiplier, such as 1, 1.25 or 2.
 *
 * Drawing larger leaves less room: at twice the size a desk 1200 across is
 * 600 wide in the units a window's own position is written in, and a window
 * at 700 is then off the screen with no way back to it. So everything is
 * gathered in afterwards.
 */
function setDeskScale(scale) {
  document.body.style.zoom = String(scale);
  gatherWindows();
}

/**
 * Brings any window that is off the desk back onto it, and makes any that is
 * larger than the desk as large as the desk, starting at its edge, which is
 * what keeps its resize bar where a pointer can reach it. A fixed window has
 * no bar and keeps its size.
 */
function gatherWindows() {
  const room = deskRoom();
  for (const window_ of document.querySelectorAll("nx-window")) {
    if (window_.hidden) continue;
    let changed = false;
    if (!window_.hasAttribute("fixed")) {
      const held = window_.sizeOnDesk(window_.offsetWidth, window_.offsetHeight);
      if (held.width < window_.offsetWidth) {
        window_.style.width = held.width + "px";
        window_.style.left = "0px";
        changed = true;
      }
      if (held.height < window_.offsetHeight) {
        window_.style.height = held.height + "px";
        window_.style.top = "0px";
        changed = true;
      }
    }
    const left = Math.min(window_.offsetLeft, Math.max(0, room.width - 90));
    const top = Math.min(window_.offsetTop, Math.max(0, room.height - 40));
    if (left !== window_.offsetLeft || top !== window_.offsetTop) {
      window_.style.left = left + "px";
      window_.style.top = top + "px";
      changed = true;
    }
    if (changed) window_.save?.();
  }
}

/* --- the two units, and the three doors between them ---------------------

   A pointer answers in the viewport's pixels, and so does
   getBoundingClientRect. Everything the desk is laid out in answers in its
   own: offsetLeft, style.left, clientHeight and a transform are all in the
   pixels an element has before zoom multiplies them.

   At twice the size a hand that traveled 100 viewport pixels has moved a
   window 50 of its own, so one cannot be subtracted from the other. There are
   three ways a viewport number reaches this desk, and each of them is a
   function below: a pointer, an element's rectangle, and the size of the
   window itself. Nothing past them divides by anything. */

/**
 * A place on the desk, in the units the desk is laid out in.
 * @typedef {{x: number, y: number}} DeskPoint
 */

/**
 * A rectangle on the desk, in the same units. A DOMRect's shape, so it goes
 * wherever one went.
 * @typedef {{left: number, top: number, width: number, height: number}} DeskRect
 */

/**
 * A size on the desk, in the same units.
 * @typedef {{width: number, height: number}} DeskSize
 */

/**
 * @param {number} length - A viewport measurement.
 * @returns {number} The same length as the desk writes it.
 */
function onDesk(length) {
  return length / deskScale();
}

/**
 * @param {PointerEvent} event
 * @returns {DeskPoint} Where the pointer is.
 */
function deskPoint(event) {
  return { x: onDesk(event.clientX), y: onDesk(event.clientY) };
}

/**
 * @overload
 * @param {Element} element
 * @returns {DeskRect}
 */
/**
 * @overload
 * @param {Element | null | undefined} element
 * @returns {DeskRect | null}
 */
/**
 * Where an element is, on the desk.
 * @param {Element | null} [element] - Anything drawn there.
 * @returns {DeskRect | null} Where it is, or null where there is no element.
 *
 * What draws a picture of something moving puts that picture against the
 * viewport, and anything put there is still a child of the body and carries
 * the desk's zoom. A rect taken straight off an element would be scaled a
 * second time by it.
 */
function deskRect(element) {
  const rect = element?.getBoundingClientRect?.();
  if (!rect) return null;
  return {
    left: onDesk(rect.left), top: onDesk(rect.top),
    width: onDesk(rect.width), height: onDesk(rect.height),
  };
}

/** @returns {DeskSize} How much room there is for windows, in the units a
 *  window's own left and top are written in, which zoom does not change. */
function deskRoom() {
  return { width: onDesk(innerWidth), height: onDesk(innerHeight) };
}

/**
 * The element of one kind an event happened in, such as the nx-thing under a
 * click.
 * @template {keyof HTMLElementTagNameMap} Tag
 * @param {Event} event - What happened.
 * @param {Tag} tag - Which kind.
 * @returns {HTMLElementTagNameMap[Tag] | null} The nearest one around where it
 *   happened, or null where it happened in none, or not in an element at all.
 */
function closestTo(event, tag) {
  return event.target instanceof Element ? event.target.closest(tag) : null;
}

/**
 * Points an element at one of the pictures build.py baked into the stylesheet.
 * @param {HTMLElement} el
 * @param {string} name - The picture's name, which is its file's stem.
 */
function showArt(el, name) {
  el.style.backgroundImage = "var(--" + name + ")";
}

/**
 * Runs a pointer gesture and reports the result when it ends.
 * @template Start
 * @param {HTMLElement} handle - Where the gesture starts.
 * @param {(point: DeskPoint, start: Start) => void} onMove - Given where the
 *   pointer is now.
 * @param {(point: DeskPoint) => Start} onStart - Whatever the mover needs to
 *   know about the moment the gesture began, given the same.
 * @param {(start: Start) => void} [onEnd] - Given what onStart returned,
 *   which by then carries whatever the moves wrote into it.
 *
 * The pointer is converted here, so what a gesture hands on is already in the
 * units of the element it moves and nothing downstream has to know the desk
 * can be drawn larger.
 */
function gesture(handle, onMove, onStart, onEnd) {
  handle.addEventListener("pointerdown", (event) => {
    event.stopPropagation();
    /* Without this the browser starts its own text selection under the
       pointer, and dragging a window paints half the desk blue. */
    event.preventDefault();
    handle.setPointerCapture(event.pointerId);
    const start = onStart(deskPoint(event));

    /* A pointer reports faster than the screen redraws, so the moves are
       coalesced into one update per frame. Everything beyond the last one in
       a frame is work whose result is painted over before anybody sees it. */
    /** @type {PointerEvent | null} */
    let latest = null;
    let frame = 0;

    const apply = () => {
      frame = 0;
      if (latest) onMove(deskPoint(latest), start);
    };

    const move = (/** @type {PointerEvent} */ moveEvent) => {
      latest = moveEvent;
      if (!frame) frame = requestAnimationFrame(apply);
    };

    const finish = () => {
      handle.removeEventListener("pointermove", move);
      /* The last position has to land before anything saves it, so a frame
         still owed is run now rather than canceled. */
      if (frame) {
        cancelAnimationFrame(frame);
        apply();
      }
      onEnd?.(start);
    };

    handle.addEventListener("pointermove", move);
    handle.addEventListener("pointerup", finish, { once: true });
    handle.addEventListener("pointercancel", finish, { once: true });
  });
}

/**
 * Moves an element by its handle, and settles it where it was let go.
 *
 * While the gesture runs the element is moved with a transform, which the
 * compositor can do without laying the page out again. Its left and top are
 * written once, at the end, so everything that reads them afterwards sees a
 * plain position and knows nothing about how it got there.
 *
 * @param {HTMLElement} element - What moves.
 * @param {HTMLElement} handle - What is grabbed.
 * @param {object} [hooks]
 * @param {() => void} [hooks.onGrab] - Called as the gesture begins.
 * @param {() => void} [hooks.onSettled] - Called once the position is written.
 */
function draggable(element, handle, { onGrab, onSettled } = {}) {
  gesture(handle,
    (point, start) => {
      /* Never past the top or left edge, and never wholly behind the dock. */
      const room = deskRoom();
      start.left = Math.max(0, Math.min(point.x - start.grabX, room.width - 90));
      start.top = Math.max(0, Math.min(point.y - start.grabY, room.height - 24));
      element.style.transform =
        `translate(${start.left - start.fromLeft}px, ${start.top - start.fromTop}px)`;
    },
    (point) => {
      onGrab?.();
      const fromLeft = element.offsetLeft;
      const fromTop = element.offsetTop;
      return {
        grabX: point.x - fromLeft, grabY: point.y - fromTop,
        fromLeft, fromTop, left: fromLeft, top: fromTop,
      };
    },
    (start) => {
      element.style.transform = "";
      element.style.left = start.left + "px";
      element.style.top = start.top + "px";
      onSettled?.();
    });
}

/* --- the desk is not a document ------------------------------------------

   A right click here opens what the thing under the pointer offers, or
   nothing. The browser's own menu is about a document: reload it, save the
   picture, look at the source. None of that is about a machine or a window,
   and NeXTSTEP never put anything of the sort on a desk.

   Refused for the whole desk, including the fields and anything a terminal
   will hold, because one rule that holds everywhere is the only kind a person
   can rely on. What has a menu of its own opens it from its own handler. */
addEventListener("contextmenu", (event) => event.preventDefault());

/* --- the desk does not hold text -----------------------------------------

   user-select says a selection may not begin inside an element. It does not
   stop a browser that begins one anyway, and a drag across a shelf then leaves
   every label it passed highlighted in the browser's own blue.

   Refused here rather than in a stylesheet, because this holds whatever the
   browser makes of the property. A terminal is the exception: reading
   something out of it is the point of having one. */
addEventListener("selectstart", (event) => {
  if (!(event.target instanceof Element && event.target.closest(".terminal"))) {
    event.preventDefault();
  }
});

/* --- the letters beside the menu entries ---------------------------------

   NeXTSTEP drew those for Command key shortcuts. Command and Control both
   belong to the browser here, so the letter acts on its own, and three
   conditions keep that from being a nuisance: nothing held down, nothing being
   typed into, and no panel up, because a panel has a keyboard of its own and
   two answers to give with it.

   A context menu is left out. Its entries act on whatever was right clicked,
   and a key press has nothing under the pointer. */
addEventListener("keydown", (event) => {
  if (event.metaKey || event.ctrlKey || event.altKey) return;
  if (document.querySelector("nx-ask[data-open]")) return;

  const focused = document.activeElement;
  if (focused?.matches("input, textarea, select")
      || (focused instanceof HTMLElement && focused.isContentEditable)) return;

  const pressed = event.key.toLowerCase();
  const item = [...document.querySelectorAll("nx-menu:not([context]) nx-menu-item[key]")]
    .find((entry) => entry.getAttribute("key")?.toLowerCase() === pressed);
  if (!(item instanceof HTMLElement) || item.hasAttribute("disabled")) return;

  event.preventDefault();
  item.click();
});

/**
 * Puts the front window back in front and every other one behind it.
 *
 * This runs over all the windows rather than inside any one of them, because
 * being in front is a statement about all of them together: a window can only
 * make itself active by making the others inactive, and at a load none of them
 * has done that yet. Without it every title bar is drawn active, which is a
 * desk NeXTSTEP never showed.
 *
 * Without a remembered name the last open window in the markup takes it, which
 * is the one a reader would call the frontmost.
 */
function restoreFront() {
  const windows = [...document.querySelectorAll("nx-window")];
  for (const window_ of windows) window_.setAttribute("inactive", "");
  const remembered = recall("desk").front;
  const open = windows.filter((window_) => !window_.hidden);
  const front = open.find((window_) => window_.name === remembered) ?? open.at(-1);
  front?.raise();
}


/**
 * Whether this browser had never been on this desk when the page loaded.
 *
 * The desk writes down where every window stands, so a store with nothing in
 * it is somebody arriving for the first time. Asked once, at load, rather than
 * whenever somebody wants to know: restoring the front window is itself
 * something worth writing down, so by the time the page is up the answer has
 * already changed.
 *
 * Read rather than kept as a flag of its own, because a second thing to write
 * down is a second thing that can disagree with the first.
 */
const DESK_WAS_NEW = Object.keys(readState()).length === 0;

/** @returns {boolean} Whether this is that browser's first visit. */
function deskIsNew() {
  return DESK_WAS_NEW;
}

/**
 * Hands the desk itself the front, which is what a press on it means.
 *
 * Every window goes inactive and none is raised, so the main menu belongs to
 * the workspace again. The event carries an empty name for the same reason:
 * there is no window in front, and whoever draws the menu reads that as the
 * workspace's own.
 *
 * NeXTSTEP activates an application when one of its windows is clicked, and
 * the desk is the Workspace's own surface. Without this it is the one thing
 * here that cannot be brought forward, and the way back to its menu is to
 * close somebody else's window.
 *
 * On the way down rather than on the click, because that is when the original
 * reorders windows, and a press that begins on the desk is the desk's however
 * far it is dragged afterwards.
 */
addEventListener("pointerdown", (event) => {
  if (event.target instanceof Element
      && event.target.closest("nx-window, nx-menu, nx-dock, nx-floor, nx-ask")) return;
  for (const window_ of document.querySelectorAll("nx-window")) {
    window_.setAttribute("inactive", "");
  }
  remember("desk", { front: "" });
  document.dispatchEvent(new CustomEvent("nx-front", { detail: { name: "" } }));
});

/* --- pictures of things moving -------------------------------------------

   Two of them, and both are pictures rather than the things themselves: an
   icon on its way to the floor of the screen, and the way from a folder to
   the place its contents will appear. Neither is asked about by anything: a
   caller says where from and where to, and waits for it to land.

   Both put their picture against the viewport, and both take their two places
   on the desk, which is what deskRect answers in. A caller reaching for
   getBoundingClientRect here would hand over the one unit that does not
   work. */

/** How long an icon takes to reach its place on the floor. Brisk, because it
 *  is a thing moving rather than an effect: long enough to be followed by the
 *  eye and short enough that anybody waits for it. */
const FLIGHT_MS = 260;

/** The same inside one window, where the way is a fraction as long. A hundred
 *  pixels crossed at the speed of half a screen reads as hesitant, so a short
 *  way is given a short time. */
const NEAR_FLIGHT_MS = 130;

/** How many rectangles the way is drawn with, and over how long. Few and
 *  fast: what is wanted is a run of outlines standing on the screen for a
 *  moment, not a box growing. */
const ZOOM_RECTANGLES = 8;
const ZOOM_MS = 200;

/** @returns {boolean} Whether the reader has asked for less movement. */
function stillness() {
  return matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/**
 * Sends a picture of an icon from one place to another.
 * @param {string} icon - Which picture.
 * @param {DeskRect} from - Where it starts.
 * @param {DeskRect} to - Where it lands.
 * @param {number} [howLong] - How long it takes, in milliseconds. The default
 *   is the way across the screen; a way inside one window is shorter and is
 *   given NEAR_FLIGHT_MS.
 * @returns {Promise<void>} Settled when it has landed.
 *
 * A transform and nothing else, so this costs the compositor and not the
 * layout. Where the reader has asked for less movement there is no flight at
 * all: the tile is simply there, which is what they asked for.
 */
function fly(icon, from, to, howLong = FLIGHT_MS) {
  if (stillness()) return Promise.resolve();

  const ghost = document.createElement("i");
  ghost.className = "art flying";
  showArt(ghost, icon);
  ghost.style.left = to.left + "px";
  ghost.style.top = to.top + "px";
  ghost.style.width = to.width + "px";
  ghost.style.height = to.height + "px";
  document.body.append(ghost);

  const across = (from.left + from.width / 2) - (to.left + to.width / 2);
  const down = (from.top + from.height / 2) - (to.top + to.height / 2);
  const smaller = to.width ? Math.max(0.2, from.width / to.width) : 1;

  const flight = ghost.animate([
    { transform: `translate(${across}px, ${down}px) scale(${smaller})` },
    { transform: "translate(0, 0) scale(1)" },
  ], { duration: howLong, easing: "ease-out" });

  return flight.finished.then(() => {}, () => {}).finally(() => ghost.remove());
}



/**
 * Draws the way from one place to another, as a run of rectangles.
 * @param {DeskRect} from - Where it starts, which is the mark around an icon.
 * @param {DeskRect} to - Where it ends, which is the box about to hold what
 *   was in that folder.
 * @returns {Promise<void>} Settled when they have gone.
 *
 * Several, and none of them is rubbed out: each is drawn at its own size a
 * moment after the last, so what stands on the screen is a run of nested
 * outlines from the icon to the band, and they all go together at the end.
 * That is what makes it read as a wave rather than as one box growing.
 *
 * Outlines rather than filled rectangles, because filled ones would be a
 * black flash across half the window.
 */
function zoom(from, to) {
  if (stillness()) return Promise.resolve();

  /** @type {HTMLElement[]} */
  const drawn = [];
  /** @type {Animation | null} */
  let last = null;
  for (let step = 1; step <= ZOOM_RECTANGLES; step += 1) {
    const part = step / ZOOM_RECTANGLES;
    const box = document.createElement("div");
    box.className = "zooming";
    box.style.left = between(from.left, to.left, part) + "px";
    box.style.top = between(from.top, to.top, part) + "px";
    box.style.width = between(from.width, to.width, part) + "px";
    box.style.height = between(from.height, to.height, part) + "px";
    box.style.opacity = "0";
    document.body.append(box);
    drawn.push(box);

    /* Turned on rather than faded in: a rectangle is there or it is not. */
    last = box.animate([{ opacity: 0 }, { opacity: 1 }], {
      duration: 1,
      delay: (step - 1) * (ZOOM_MS / ZOOM_RECTANGLES),
      fill: "forwards",
    });
  }

  return (last ? last.finished : Promise.resolve())
    .then(() => {}, () => {})
    .finally(() => drawn.forEach((box) => box.remove()));
}

/**
 * @param {number} start
 * @param {number} end
 * @param {number} part - Where between them, from zero to one.
 * @returns {number} Rounded, because a rectangle drawn on half a pixel is a
 *   gray line rather than a black one.
 */
function between(start, end, part) {
  return Math.round(start + (end - start) * part);
}

/* --- nx-window ---------------------------------------------------------- */

/**
 * A window: title bar, close button, optional resize bar, and a memory.
 *
 * It writes its position, its size and whether it is open under its name, so
 * the desk comes back the way it was left. A window marked `fixed` has no
 * resize bar, one marked `flush` lets its content run to the frame, and one
 * marked `drop` accepts things dragged onto it.
 *
 * @attr name   - What it is called in storage and to the menu. Required.
 * @attr title  - The text in the bar.
 * @attr x y w h - Where it starts, before anything was remembered.
 * @attr min-w min-h - The floor its content needs.
 *
 * @fires nx-front - It has come to the front, carrying its `name`. The main
 *   menu belongs to whatever is in front, so this is what it follows.
 */
class NxWindow extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    const content = [...this.childNodes];
    this.replaceChildren();

    /** @type {HTMLElement} */
    this.bar = this.build("div", "titlebar");
    this.bar.append(this.build("i", "art wbtn mini"));
    const title = this.build("div", "title");
    title.textContent = this.getAttribute("title") ?? "";
    this.removeAttribute("title");         /* or the browser shows a tooltip */
    const close = this.build("i", "art wbtn close");
    this.bar.append(title, close);

    /** @type {HTMLElement} */
    this.pane = this.build("div", "pane");
    this.pane.append(...content);
    this.append(this.bar, this.pane);

    if (!this.hasAttribute("fixed")) this.addResizer();
    if (this.hasAttribute("drop")) this.acceptDrops();
    this.place();
    this.wire(close);
  }

  /**
   * Puts a different name in the title bar.
   * @param {string} text - What the window is about now.
   *
   * For a window that says something about whatever was chosen, where the
   * name is the difference between two of them.
   */
  rename(text) {
    const title = this.bar?.querySelector(".title");
    if (title) title.textContent = text;
  }

  /**
   * @param {string} tag - Which element.
   * @param {string} className - What the stylesheet knows it by.
   * @returns {HTMLElement} A child element, appended nowhere yet.
   */
  build(tag, className) {
    const el = document.createElement(tag);
    el.className = className;
    return el;
  }

  /** Puts the window where it was left, or where its attributes say. */
  place() {
    const saved = recall(this.name);
    /** @type {(key: "x" | "y" | "w" | "h", attribute: string) => number} */
    const number = (key, attribute) => saved[key] ?? Number(this.getAttribute(attribute));
    /* A window nobody can resize has no size of its own to remember, so its
       markup decides. Otherwise a size saved before it was fixed, or before
       its contents changed, would outlive both. */
    const fixed = this.hasAttribute("fixed");
    /** @type {typeof number} */
    const size = fixed
      ? (_key, attribute) => Number(this.getAttribute(attribute))
      : number;

    /* Before the size, because the floor is read off these and a size saved
       when the window held something else has to be held to what it holds
       now. */
    for (const [attribute, property] of [["min-w", "--win-min-w"], ["min-h", "--win-min-h"]]) {
      if (this.hasAttribute(attribute)) {
        this.style.setProperty(property, this.getAttribute(attribute) + "px");
      }
    }
    const wanted = { width: size("w", "w"), height: size("h", "h") };
    const held = this.sizeOnDesk(wanted.width, wanted.height);

    /* With at least a corner of its title bar on the desk. A window cut down
       to the size of the desk starts at that edge, because anywhere further
       along its resize bar would be off the desk again. */
    const room = deskRoom();
    this.style.left = (held.width < wanted.width
      ? 0 : Math.min(number("x", "x"), Math.max(0, room.width - 90))) + "px";
    this.style.top = (held.height < wanted.height
      ? 0 : Math.min(number("y", "y"), Math.max(0, room.height - 40))) + "px";

    this.style.width = held.width + "px";

    /* A fixed window is as tall as what is in it, unless its markup says
       otherwise. A height written by hand is a number that stops being right
       the moment a row is added, and both windows here had drifted that way.
       Width stays a decision, because a column of readings has no natural
       one. */
    this.style.height = fixed && !this.hasAttribute("h")
      ? "auto"
      : held.height + "px";
    /* A window is open unless it says otherwise, and what was remembered
       beats what the markup starts it at. */
    this.hidden = !(saved.open ?? !this.hasAttribute("closed"));
  }

  /** @returns {string} The name it is known by, which every window carries. */
  get name() { return this.getAttribute("name") ?? ""; }

  /**
   * A size this window can have on the desk as it is now.
   * @param {number} width - The width wanted, in the window's own units.
   * @param {number} height - The height wanted.
   * @returns {DeskSize} Each side at least the floor its content needs and no
   *   larger than the desk.
   *
   * No larger than the desk, because the resize bar runs along the window's
   * foot and its title bar cannot be taken above the top edge: a window taller
   * than the desk has its bar out of reach for good, and the desk remembers it
   * that way. The floor wins where the desk is smaller than the floor.
   */
  sizeOnDesk(width, height) {
    const floor = this.floor;
    const room = deskRoom();
    return {
      width: Math.max(floor.width, Math.min(width, room.width)),
      height: Math.max(floor.height, Math.min(height, room.height)),
    };
  }

  /** @returns {DeskSize} The floor this window's content needs, read off the
   *  element itself. */
  get floor() {
    const style = getComputedStyle(this);
    return {
      width: parseInt(style.getPropertyValue("--win-min-w"), 10),
      height: parseInt(style.getPropertyValue("--win-min-h"), 10),
    };
  }

  /**
   * Saves whether it is open, and where and how big it is.
   *
   * A hidden element measures zero on every side, so a closed window keeps the
   * geometry it had rather than writing that over with nothing. Otherwise it
   * would come back in the corner at no size at all.
   */
  save() {
    /** @type {Remembered} */
    const state = { open: !this.hidden };
    if (!this.hidden) {
      Object.assign(state, {
        x: this.offsetLeft, y: this.offsetTop,
        w: this.offsetWidth, h: this.offsetHeight,
      });
    }
    remember(this.name, state);
  }

  /**
   * Brings it forward and pushes every other window back. Which window is in
   * front is part of what the desk remembers, because exactly one is active at
   * a time and a reload that made them all active would be a desk nobody has
   * ever seen.
   *
   * @fires nx-front - Only where something changed, so a window already in
   *   front raises nothing and the menu is not rewritten for nothing.
   */
  raise() {
    if (!this.hasAttribute("inactive") && this.style.zIndex) return;
    let highest = 10;
    for (const other of document.querySelectorAll("nx-window")) {
      highest = Math.max(highest, Number(other.style.zIndex) || 10);
      other.setAttribute("inactive", "");
    }
    this.style.zIndex = String(highest + 1);
    this.removeAttribute("inactive");
    remember("desk", { front: this.name });
    /* The main menu belongs to whatever is in front, so the one thing that
       decides which window that is has to say when it changes. */
    this.dispatchEvent(new CustomEvent("nx-front", {
      bubbles: true,
      detail: { name: this.name },
    }));
  }

  /**
   * Shows it, in front.
   * @param {Element | null} [asker] - What was used to open it, if anything was.
   *   It rides along as a rectangle, because an application whose icon has to
   *   travel to the foot of the screen has to know where it is traveling
   *   from, and only whoever was clicked knows that.
   */
  open(asker) {
    this.hidden = false;
    this.raise();
    this.save();
    /* So whatever fills this window can fill it now rather than at the next
       poll, which is up to five seconds of dashes. */
    this.dispatchEvent(new CustomEvent("nx-open", {
      bubbles: true,
      detail: { from: deskRect(asker) },
    }));
  }

  /** Hides it, keeping its geometry for the next time.
   *
   * Says so as it goes, because what a window holds may be more than a
   * drawing: a session on the other side of a socket has to be told that
   * nobody is looking any more.
   */
  close() {
    this.hidden = true;
    /* A window that is not on the screen is not the active one, and saying so
       is what lets it come to the front again: raise does nothing for a
       window that already believes it is there, so without this a window
       closed and opened again would arrive silently and the menu would go on
       showing whatever was in front before it. */
    this.setAttribute("inactive", "");
    this.save();
    this.dispatchEvent(new CustomEvent("nx-close", { bubbles: true }));
  }

  /**
   * Takes what is dropped on it, and says so while something is over it.
   *
   * Raises the same `nx-choose` a double click does, because carrying a thing
   * here and double clicking it mean the same thing to whoever answers.
   */
  acceptDrops() {
    this.addEventListener("dragover", (event) => {
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = "copy";
      this.setAttribute("droppable", "");
    });

    /* Moving onto a child fires dragleave on the parent, so only a pointer
       that has actually left the window counts. */
    this.addEventListener("dragleave", (event) => {
      const into = event.relatedTarget;
      if (!(into instanceof Node && this.contains(into))) this.removeAttribute("droppable");
    });

    this.addEventListener("drop", (event) => {
      event.preventDefault();
      this.removeAttribute("droppable");
      this.dispatchEvent(new CustomEvent("nx-choose", {
        bubbles: true,
        detail: { value: event.dataTransfer?.getData("text/plain") ?? "" },
      }));
    });
  }

  /** The bar along the foot: a middle that takes the height and two ends that
   *  take the corner with it. */
  addResizer() {
    const bar = this.build("div", "resizer");
    const left = this.build("div", "end");
    const middle = this.build("div", "middle");
    const right = this.build("div", "end");
    left.dataset.corner = "left";
    right.dataset.corner = "right";
    bar.append(left, middle, right);
    this.append(bar);

    for (const handle of [left, middle, right]) {
      const corner = handle.dataset.corner;
      gesture(handle,
        (point, start) => {
          const floor = this.floor;
          const room = deskRoom();
          /* No further than the desk's bottom and right edge, so the bar stays
             where a pointer can take hold of it again. The pointer itself goes
             further, because the gesture holds on to it outside the page. */
          this.style.height = Math.max(floor.height,
            Math.min(start.height + point.y, room.height - this.offsetTop)) + "px";
          if (corner === "right") {
            this.style.width = Math.max(floor.width,
              Math.min(start.width + point.x, room.width - this.offsetLeft)) + "px";
          } else if (corner === "left") {
            /* Dragging the left end moves that edge and holds the right one
               still, so the two have to change together. Not past the desk's
               left edge either. */
            const left = Math.max(0, Math.min(point.x - start.grabX, start.right - floor.width));
            this.style.left = left + "px";
            this.style.width = (start.right - left) + "px";
          }
        },
        (point) => {
          this.raise();
          return {
            width: this.offsetWidth - point.x,
            height: this.offsetHeight - point.y,
            grabX: point.x - this.offsetLeft,
            right: this.offsetLeft + this.offsetWidth,
          };
        },
        () => this.save());
    }
  }

  /** Dragging by the bar, closing by the button, raising by a click anywhere.
   *  @param {HTMLElement} close - The close button. */
  wire(close) {
    draggable(this, this.bar, {
      onGrab: () => this.raise(),
      onSettled: () => this.save(),
    });

    close.addEventListener("click", (event) => {
      event.stopPropagation();
      this.close();
    });
    /* The bar's own gesture would otherwise start a drag from the button, and
       the window would follow the pointer as it closed. */
    close.addEventListener("pointerdown", (event) => event.stopPropagation());

    this.addEventListener("pointerdown", () => this.raise());
  }
}

/* --- nx-menu ------------------------------------------------------------ */

/**
 * The menu: a title that drags the whole thing, and entries beneath it.
 * @attr name - What it is called in storage.
 * @attr title - The text in its black bar.
 * @attr x y - Where it starts.
 */
class NxMenu extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    const title = document.createElement("div");
    title.className = "title";
    title.textContent = this.getAttribute("title") ?? "";
    this.removeAttribute("title");
    this.prepend(title);

    /* Whether to keep a column for pictures is the menu's decision and not
       each entry's: the words line up when every entry holds the place, and a
       menu where nothing has a picture would indent all of them for nothing. */
    this.toggleAttribute("with-icons", Boolean(this.querySelector("nx-menu-item[icon]")));

    /* A menu that answers a right click is the same menu, put where the
       pointer is and taken away again. It is not carried about and not
       remembered, so it neither drags nor saves. */
    if (this.hasAttribute("context")) {
      this.hidden = true;
      return;
    }

    const name = this.getAttribute("name") ?? "";
    const saved = recall(name);
    this.style.left = (saved.x ?? Number(this.getAttribute("x"))) + "px";
    this.style.top = (saved.y ?? Number(this.getAttribute("y"))) + "px";

    draggable(this, title, {
      onSettled: () => remember(name, { x: this.offsetLeft, y: this.offsetTop }),
    });
  }

  /**
   * Shows the entries belonging to one application, under its name.
   * @param {string} owner - What the entries say they belong to through
   *   their own `for`, or "" for the ones the workspace itself owns.
   * @param {string} title - What to put in the bar.
   *
   * One menu rather than one per application, which is what NeXTSTEP had:
   * the menu stays where somebody dragged it and its contents change under
   * the title. Every entry is in the markup and the ones that do not belong
   * are hidden, so nothing is built or thrown away and the strings in them
   * are written once for all of them.
   */
  showFor(owner, title) {
    const bar = this.querySelector(":scope > .title");
    if (bar) bar.textContent = title;

    /** @type {NxMenuItem | null} */
    let last = null;
    const entries = /** @type {NodeListOf<NxMenuItem>} */ (
      this.querySelectorAll(":scope > nx-menu-item"));
    for (const entry of entries) {
      /* `away` is an entry that is not in this menu at all just now, which is
         the page's to say: an entry about a machine, on a desk where none is
         installed, is a question with no answer. `hidden` stays this menu's
         own, so the two never write over each other, and an entry that is away
         is not the last one either. */
      const belongs = (entry.getAttribute("for") ?? "") === owner
        && !entry.hasAttribute("away");
      entry.hidden = !belongs;
      entry.removeAttribute("last");
      if (belongs) last = entry;
    }
    /* The foot of the menu is drawn on the last entry that is showing, which
       is not the last child once some of them are hidden. */
    last?.setAttribute("last", "");
  }

  /**
   * Puts a context menu at the pointer and takes it away on the next click.
   * @param {number} x - Where the pointer was, as an event reports it.
   * @param {number} y
   *
   * A pointer's own coordinates, so that whoever answers a right click can
   * pass on what the event handed them without knowing how large the desk is
   * drawn. Converted here, where the menu's own position is written.
   */
  openAt(x, y) {
    this.hidden = false;
    /* Measured after it is shown, because a hidden element has no size, and
       kept inside the window so a menu near an edge is not half off it. */
    const own = deskRect(this);
    const room = deskRoom();
    this.style.left = Math.min(onDesk(x), room.width - own.width - 2) + "px";
    this.style.top = Math.min(onDesk(y), room.height - own.height - 2) + "px";

    const away = (/** @type {PointerEvent} */ event) => {
      if (event.target instanceof Node && this.contains(event.target)) return;
      this.close();
    };
    /** @type {(() => void) | null} */
    this.dismiss = () => {
      removeEventListener("pointerdown", away, true);
      removeEventListener("keydown", escape);
    };
    const escape = (/** @type {KeyboardEvent} */ event) => {
      if (event.key === "Escape") this.close();
    };
    addEventListener("pointerdown", away, true);
    addEventListener("keydown", escape);
  }

  /** Takes it away, and stops listening for what would have. */
  close() {
    this.hidden = true;
    this.dismiss?.();
    this.dismiss = null;
  }
}

/**
 * One entry. With `opens` it shows that window, raising it when it is already
 * up, which is what the original did with an entry for a window on screen.
 * @attr opens - The name of an nx-window.
 * @attr key - The letter shown on the right.
 */
class NxMenuItem extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    /* Every entry gets the place, whether it has a picture for it or not, so
       the words all begin at the same column. */
    const art = document.createElement("i");
    art.className = "art mark";
    const icon = this.getAttribute("icon");
    if (icon !== null) showArt(art, icon);
    this.prepend(art);
    if (this.hasAttribute("key")) {
      const key = document.createElement("span");
      key.className = "key";
      key.textContent = this.getAttribute("key");
      this.append(key);
    }
    const target = this.getAttribute("opens");
    if (target) {
      this.addEventListener("click", () => {
        if (this.hasAttribute("disabled")) return;
        /** @type {NxWindow | null} */ (
          document.querySelector(`nx-window[name="${target}"]`))?.open(this);
      });
    }
  }
}

/* --- nx-popup ----------------------------------------------------------- */

/**
 * One choice a pop-up list offers.
 * @typedef {object} PopupChoice
 * @property {string} value - What `nx-pick` carries when it is chosen.
 * @property {string} label - What the list and the button show for it.
 */

/**
 * A pop-up list: a button labeled with what is chosen and marked with NeXT's
 * pop-up mark, and the list of choices that comes up while it is held.
 *
 * Chapter 7 of NeXTSTEP's interface guidelines says how it goes: the list is
 * there only while the mouse stays down, placed so the item that matches the
 * label sits over the button, and letting go over another item chooses it and
 * changes the label. A press and a release without moving chooses what was
 * chosen, which changes nothing. The chapter gives a pop-up list no keyboard,
 * and neither does this.
 *
 * Raises `nx-pick` carrying the value chosen, and only where it changed. Not
 * `nx-choose`, which the File Viewer's things raise and the page answers by
 * opening whatever was chosen.
 *
 * With fewer than two choices there is nothing to choose between, so the
 * button greys its label and does nothing, which is what the chapter asks of a
 * button that would do nothing.
 */
class NxPopup extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;
    this.choices ??= [];

    /** @type {HTMLButtonElement} */
    this.button = document.createElement("button");
    this.button.type = "button";
    this.button.className = "popup-button";
    /** @type {HTMLSpanElement} */
    this.label = document.createElement("span");
    this.label.className = "popup-label";
    const mark = document.createElement("i");
    mark.className = "popup-mark";
    this.button.append(this.label, mark);
    this.append(this.button);

    this.button.addEventListener("pointerdown", (event) => this.held(event));
    this.drawLabel();
  }

  /**
   * Says what can be chosen, and which of it is.
   * @param {PopupChoice[]} choices - In the order the list shows them.
   * @param {string | null} [value] - The one chosen, the first where none is
   *   named or the one named is not among them.
   */
  offer(choices, value) {
    /** @type {PopupChoice[]} */
    this.choices = choices;
    const named = choices.find((choice) => choice.value === value);
    /** @type {string} */
    this.value = named ? named.value : choices[0]?.value ?? "";
    this.drawLabel();
  }

  /** Writes the chosen one onto the button, and greys it where there is
   *  nothing to choose between. */
  drawLabel() {
    if (!this.button) return;
    this.label.textContent =
      this.choices.find((choice) => choice.value === this.value)?.label ?? "";
    this.button.disabled = this.choices.length < 2;
  }

  /**
   * Brings the list up for as long as the button is held.
   * @param {PointerEvent} event - The press.
   *
   * The list goes onto the desk rather than into the window, because it is a
   * spring-loaded window of its own: it stands above everything, panels
   * included, and nothing it covers can hold it in.
   */
  held(event) {
    if (event.button !== 0 || this.button.disabled) return;
    event.preventDefault();

    /* The entries are menu entries, which is what NeXTSTEP drew a pop-up
       list's items as, so they wear exactly what an entry of the menu wears. */
    const list = document.createElement("div");
    list.className = "popup-list";
    for (const choice of this.choices) {
      const item = document.createElement("nx-menu-item");
      item.dataset.value = choice.value;
      item.textContent = choice.label;
      item.toggleAttribute("lit", choice.value === this.value);
      list.append(item);
    }
    document.body.append(list);
    this.place(list);

    const under = (/** @type {PointerEvent} */ pointer) => document
      .elementFromPoint(pointer.clientX, pointer.clientY)
      ?.closest(".popup-list nx-menu-item");
    const follow = (/** @type {PointerEvent} */ pointer) => {
      const item = under(pointer);
      for (const each of list.children) each.toggleAttribute("lit", each === item);
    };
    const finish = (/** @type {PointerEvent} */ pointer) => {
      removeEventListener("pointermove", follow);
      removeEventListener("pointercancel", finish);
      const item = pointer.type === "pointerup" ? under(pointer) : null;
      list.remove();
      if (item instanceof HTMLElement && item.dataset.value !== this.value) {
        this.value = item.dataset.value ?? "";
        this.drawLabel();
        this.dispatchEvent(new CustomEvent("nx-pick", {
          detail: { value: this.value }, bubbles: true }));
      }
    };
    addEventListener("pointermove", follow);
    addEventListener("pointerup", finish, { once: true });
    addEventListener("pointercancel", finish, { once: true });
  }

  /**
   * Puts the list where the chosen item lies over the button.
   * @param {HTMLElement} list - The list, already on the desk so it has a size.
   *
   * Held inside the desk, because a list that runs off it has items nobody can
   * reach. That moves the chosen item off the button near an edge, which is
   * what the chapter warns of and why it advises against a pop-up list there.
   */
  place(list) {
    const button = deskRect(this.button);
    list.style.minWidth = button.width + "px";
    const own = deskRect(list);
    const first = deskRect(list.firstElementChild);
    const row = first?.height ?? 0;
    /* The list's own edge stands above its first item, and the chosen item is
       centered on the button rather than aligned with its top, because the two
       are not the same height. */
    const edge = first ? first.top - own.top : 0;
    const at = Math.max(0, this.choices.findIndex((choice) => choice.value === this.value));
    const top = button.top + (button.height - row) / 2 - edge - at * row;
    const room = deskRoom();
    list.style.left = Math.max(0, Math.min(button.left, room.width - own.width)) + "px";
    list.style.top = Math.max(0, Math.min(top, room.height - own.height)) + "px";
  }
}

/* --- nx-dock ------------------------------------------------------------ */

/** How far the pointer may wander before it is carrying a tile rather than
 *  clicking one. A tile is opened with a double click, and a hand that moves
 *  a pixel between the two clicks must not leave the tile a slot lower. */
const GRIP_PX = 4;

/**
 * The dock: a column of slots, one tile high, that a person arranges.
 *
 * A tile is lifted out of the column by dragging it, carried up and down, and
 * set down on a slot that is free. While it travels, the slot it would land
 * on shows itself. Letting go anywhere else puts it back where it came from,
 * because a tile can only be somewhere in the dock.
 *
 * Where a tile ends up is remembered under its name, so a tile that is to
 * keep its place across a reload needs one. The Workspace tile carries
 * `fixed` instead: NeXTSTEP kept it at the head of the dock, and it is the
 * one tile there is nothing to remember about.
 */
class NxDock extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    /** @type {HTMLElement} */
    this.mark = document.createElement("i");
    this.mark.className = "slot";

    this.arrange();
    for (const tile of this.tiles) {
      if (!tile.hasAttribute("fixed")) this.carry(tile);
    }

    /* A window made shorter can leave a tile on a slot that is no longer on
       the screen. Arranging again puts it on the nearest free one, and
       because only letting go of a tile writes anything down, making the
       window tall again brings it back to where it was put. */
    addEventListener("resize", () => this.arrange());
  }

  /** @returns {NxTile[]} The tiles in the column, in markup order. */
  get tiles() {
    return [...this.querySelectorAll("nx-tile")];
  }

  /** @returns {number} How tall one slot is, which is how tall a tile is. */
  get step() {
    return parseFloat(getComputedStyle(this).getPropertyValue("--dock-width"));
  }

  /** @returns {number} How many slots are on the screen. */
  get slots() {
    return Math.max(1, Math.floor(deskRoom().height / this.step));
  }

  /**
   * Puts every tile on a slot.
   *
   * The fixed ones take the ends of the column in markup order, the head by
   * default and the foot where they say so. Everything else goes back to
   * where it was left, and anything without a place to go back to, or whose
   * place is taken or off the screen, takes the first slot that is free.
   */
  arrange() {
    const saved = recall("dock").places ?? {};
    /** @type {Set<number>} */
    const taken = new Set();
    const put = (/** @type {HTMLElement} */ tile, /** @type {number} */ slot) => {
      taken.add(slot);
      tile.style.gridRow = String(slot);
    };
    const open = (/** @type {number} */ slot) =>
      slot >= 1 && slot <= this.slots && !taken.has(slot);

    const fixed = this.tiles.filter((tile) => tile.hasAttribute("fixed"));
    fixed.filter((tile) => !tile.hasAttribute("foot"))
      .forEach((tile, index) => put(tile, index + 1));
    const feet = fixed.filter((tile) => tile.hasAttribute("foot"));
    feet.forEach((tile, index) => put(tile, this.slots - feet.length + 1 + index));

    /** @type {HTMLElement[]} */
    const waiting = [];
    for (const tile of this.tiles.filter((tile) => !tile.hasAttribute("fixed"))) {
      const name = tile.getAttribute("name");
      const slot = name === null ? undefined : saved[name];
      if (slot !== undefined && Number.isInteger(slot) && open(slot)) put(tile, slot);
      else waiting.push(tile);
    }
    for (const tile of waiting) {
      let slot = 1;
      while (!open(slot)) slot += 1;
      put(tile, slot);
    }
  }

  /** @param {HTMLElement} tile @returns {number} Which slot it is on. */
  slotOf(tile) {
    return Number(tile.style.gridRow);
  }

  /**
   * @param {number} slot - Which one.
   * @param {HTMLElement} carried - The tile on its way, which does not count
   *   as being in the way of itself.
   * @returns {boolean} Whether a tile may be set down there.
   */
  isFree(slot, carried) {
    if (!(slot >= 1 && slot <= this.slots)) return false;
    return !this.tiles.some(
      (tile) => tile !== carried && this.slotOf(tile) === slot);
  }

  /**
   * @param {number} top - How far down the column something sits.
   * @returns {number} The slot its middle is over.
   */
  slotUnder(top) {
    const middle = top + this.step / 2;
    return Math.min(this.slots, Math.max(1, Math.floor(middle / this.step) + 1));
  }

  /**
   * Shows which slot a traveling tile would land on.
   * @param {number} slot - Which one, or 0 for none, which is what letting go
   *   over an occupied slot means.
   */
  aimAt(slot) {
    if (!slot) {
      this.mark.remove();
      return;
    }
    this.mark.style.gridRow = String(slot);
    if (!this.mark.isConnected) this.append(this.mark);
  }

  /**
   * Sets a tile down and writes where it went.
   * @param {HTMLElement} tile
   * @param {number} slot
   */
  settle(tile, slot) {
    tile.style.gridRow = String(slot);
    const name = tile.getAttribute("name");
    if (!name) return;
    remember("dock", { places: { ...(recall("dock").places ?? {}), [name]: slot } });
  }

  /**
   * Lets one tile be carried up and down the column.
   * @param {HTMLElement} tile
   *
   * Only up and down, because the dock is one tile wide and a tile has
   * nowhere else to be. It is moved with a transform while it travels, so
   * the column it is leaving is not laid out again on every frame, and its
   * slot is written once at the end.
   */
  carry(tile) {
    gesture(tile,
      (point, start) => {
        const moved = point.y - start.grabbedAt;
        if (!start.carrying && Math.abs(moved) < GRIP_PX) return;

        start.carrying = true;
        tile.setAttribute("carried", "");
        tile.style.transform = `translateY(${moved}px)`;
        start.landing = this.slotUnder(start.from + moved);
        this.aimAt(this.isFree(start.landing, tile) ? start.landing : 0);
      },
      (point) => ({
        grabbedAt: point.y,
        from: tile.offsetTop,
        carrying: false,
        landing: 0,
      }),
      (start) => {
        tile.style.transform = "";
        tile.removeAttribute("carried");
        this.aimAt(0);
        if (start.carrying && this.isFree(start.landing, tile)) {
          this.settle(tile, start.landing);
        }
      });
  }
}

/**
 * One tile, in the dock or on the floor of the screen.
 * @attr icon - Which picture it carries.
 * @attr opens - The name of an nx-window, if it starts one.
 * @attr idle - Draw the three marks that say the application is not running.
 * @attr fixed - Stay where it is put and refuse to be carried. The Workspace
 *   tile carries this, because NeXTSTEP kept it at the head of the dock.
 * @attr foot - With `fixed`, sit at the foot of the column rather than at its
 *   head.
 * @attr carried - Set while it is being dragged, and taken off when it lands.
 *
 * A double click starts it and a single click does nothing, which is what the
 * OpenStep guidelines require and why: a tile is moved by dragging it, and a
 * click that acted would fire whenever somebody began a drag and thought
 * better of it. It also keeps this the same as the File Viewer, where one
 * click chooses and two open.
 */
class NxTile extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    const art = document.createElement("i");
    art.className = "art";
    showArt(art, this.getAttribute("icon") ?? "");
    this.append(art);

    const target = this.getAttribute("opens");
    if (target) {
      this.addEventListener("dblclick", () => {
        if (this.hasAttribute("disabled")) return;
        /** @type {NxWindow | null} */ (
          document.querySelector(`nx-window[name="${target}"]`))?.open(this);
      });
    }
  }
}

/**
 * An application's tile on the floor.
 * @typedef {object} FloorTile
 * @property {string} icon - Which picture it carries.
 * @property {string} opens - The name of the window it stands for.
 */

/**
 * Where an application that is not in the dock puts its icon.
 *
 * NeXTSTEP stacked those along the foot of the screen from the left corner
 * rightwards, and took each away when its application went. The tile is the
 * dock's own: `Workspace.app/tile.tiff` is a plain gray square with the icon
 * on it and no lettering, and that is what a tile here already is.
 *
 * An application that has just been started does not simply appear there. Its
 * icon travels from whatever was used to start it, and the tile is in place
 * when it lands.
 */
class NxFloor extends HTMLElement {
  /**
   * Puts the icons there, in the order they were started.
   * @param {FloorTile[]} running - One for each.
   * @param {{opens: string, from: DeskRect | null}} [arriving] - The one that
   *   has just started, and where it is coming from. Left out, everything is
   *   simply drawn.
   * @returns {Promise<void>} Settled once what arrived has landed.
   */
  async show(running, arriving) {
    const tiles = running.map((application) => this.tile(application));
    const newcomer = arriving && tiles.find(
      (tile) => tile.getAttribute("opens") === arriving.opens);

    if (!newcomer || !arriving.from) {
      this.replaceChildren(...tiles);
      return;
    }

    /* Drawn first and hidden, so the place it is flying to is the place it
       will actually take: the tiles beside it decide that, not this one. */
    this.replaceChildren(...tiles);
    newcomer.style.visibility = "hidden";
    await fly(newcomer.getAttribute("icon") ?? "", arriving.from, deskRect(newcomer));
    newcomer.style.visibility = "";
  }

  /**
   * @param {FloorTile} application - What to draw.
   * @returns {NxTile} One tile for an application.
   */
  tile(application) {
    const tile = document.createElement("nx-tile");
    tile.setAttribute("icon", application.icon);
    tile.setAttribute("opens", application.opens);
    return tile;
  }
}

/* --- nx-scroller -------------------------------------------------------- */

/** What differs between the two directions, so that everything else does not
 *  have to know there are two. Each value names a property of an element, a
 *  style or a point, so the checker holds every lookup below to one that
 *  exists. */
const WAYS = /** @type {const} */ ({
  down: {
    steps: ["up", "down"],
    length: "scrollHeight", showing: "clientHeight", along: "scrollTop",
    edge: "top", size: "height", pointer: "y", offset: "offsetTop",
    room: "clientHeight", trailing: "paddingBottom",
  },
  across: {
    steps: ["left", "right"],
    length: "scrollWidth", showing: "clientWidth", along: "scrollLeft",
    edge: "left", size: "width", pointer: "x", offset: "offsetLeft",
    room: "clientWidth", trailing: "paddingRight",
  },
});

/** One of the two directions. @typedef {keyof typeof WAYS} Way */

/** What one direction differs in. @typedef {typeof WAYS[Way]} WayParts */

/**
 * One scroller, as addBar builds it.
 * @typedef {object} Bar
 * @property {HTMLDivElement} trough - The checkered track.
 * @property {HTMLDivElement} knob - What a person drags.
 * @property {HTMLDivElement} arrows - Both arrows, at the far end.
 * @property {WayParts} how - Which direction it scrolls in.
 */

/**
 * A view with NeXT's scroller on its left: a checkered trough, a knob that
 * takes its size from how much of the content is showing, and both arrows at
 * the far end. With nothing to scroll the whole bar goes empty, which is how
 * an idle terminal looks.
 *
 * @attr bars - Which scrollers this view has: "down", "across", or both.
 *   A view says so because the original's do: the File Viewer's contents have
 *   both, and the band above them, which is a path and only ever grows
 *   sideways, has the one along its foot and nothing down its side. Left out,
 *   it is the vertical one alone, which is what a list wants.
 *
 * A scroller is there whether or not there is anything to scroll. It is part
 * of the view rather than something that appears when it is needed, and an
 * empty trough is what the original shows.
 */
class NxScroller extends HTMLElement {
  /** @type {HTMLElement | undefined} What the bars move, once there is one. */
  view;

  /** @type {(() => void) | undefined} What the view's scrolling calls, made
   *  once so that it can be taken off again. */
  onScroll;

  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    /* Taken before the bars exist. Each of them is prepended, so afterwards
       the first child is a bar and not the view. */
    const view = this.firstElementChild;

    const wanted = (this.getAttribute("bars") || "down").split(/\s+/);
    /** @type {Partial<Record<Way, Bar>>} */
    this.bars = {};
    for (const way of /** @type {Way[]} */ (["down", "across"])) {
      if (wanted.includes(way)) this.bars[way] = this.addBar(way);
    }

    this.drive(view);
  }

  /**
   * Points the bars at whatever actually scrolls.
   * @param {Element | null} view - The element whose scrollTop the knob
   *   moves. Nothing happens where there is none.
   *
   * The child of this element, ordinarily. Some views scroll something of
   * their own further in, because a library built the markup: a terminal
   * draws its lines into a viewport it owns, and that viewport is what
   * scrolls. Such a view says so by calling this once it exists, and the bars
   * follow it from then on.
   */
  drive(view) {
    if (!(view instanceof HTMLElement) || view === this.view) return;

    this.watch?.forEach((observer) => observer.disconnect());
    this.onScroll ??= () => this.refresh();
    this.view?.removeEventListener("scroll", this.onScroll);

    this.view = view;
    view.addEventListener("scroll", this.onScroll);

    /* What there is to scroll is the content's size against the view's, so
       both sizes are watched: the view's own, and that of every child it
       holds. A child changes size for more reasons than being replaced: a
       part inside it shown or hidden, as Preferences does when it changes
       module, a word set on it that a rule matches, a face arriving. None of
       those is a change to the list of children, and a knob drawn for the
       module before stays standing over the one after.

       The list of children is watched as well, because a child that is
       replaced has to be watched in its place, and text that changes inside
       a box of a fixed size moves no edge. */
    const sized = new ResizeObserver(() => this.refresh());
    const watchTheContent = () => {
      sized.disconnect();
      sized.observe(view);
      for (const child of view.children) sized.observe(child);
    };
    watchTheContent();
    const changed = new MutationObserver((records) => {
      if (records.some((record) => record.target === view
                       && record.type === "childList")) watchTheContent();
      this.refresh();
    });
    changed.observe(view, { childList: true, subtree: true, characterData: true });
    this.watch = [sized, changed];

    /* Says in the markup that the child is not what scrolls, so the stylesheet
       can leave the child's own overflow alone. Asked of the view's own
       parent rather than of this element's first child, which by now is a
       bar. */
    this.toggleAttribute("inner", view.parentElement !== this);
    this.refresh();
  }

  /**
   * Builds one scroller.
   * @param {Way} way - Which direction it scrolls in.
   * @returns {Bar} Its trough, its knob and its arrows.
   */
  addBar(way) {
    const how = WAYS[way];
    const bar = document.createElement("div");
    bar.className = way === "across" ? "bar across" : "bar";
    const trough = document.createElement("div");
    trough.className = "trough";
    const knob = document.createElement("div");
    knob.className = "knob";
    trough.append(knob);

    const arrows = document.createElement("div");
    arrows.className = "arrows";
    for (const step of how.steps) {
      const one = document.createElement("div");
      one.className = "step " + step;
      one.append(document.createElement("i"));
      one.addEventListener("pointerdown", (event) => {
        event.stopPropagation();
        if (!this.view) return;
        const back = step === "up" || step === "left";
        this.view[how.along] += (back ? -1 : 1) * NxScroller.LINE;
      });
      arrows.append(one);
    }
    bar.append(trough, arrows);
    this.prepend(bar);

    gesture(knob,
      (point, start) => {
        const view = this.view;
        if (!view) return;
        const room = trough[how.room] - knob[how.size === "height" ? "offsetHeight" : "offsetWidth"];
        const at = Math.max(0, Math.min(point[how.pointer] - start.grab, room));
        view[how.along] = (at / room) * (view[how.length] - view[how.showing]);
      },
      (point) => ({ grab: point[how.pointer] - knob[how.offset] }));

    return { trough, knob, arrows, how };
  }

  /** Redraws both bars from the view's current state, where there is a view. */
  refresh() {
    const view = this.view;
    if (!view) return;
    for (const bar of Object.values(this.bars)) this.fit(bar, view);
  }

  /**
   * Draws one bar.
   * @param {Bar} bar - What addBar returned.
   * @param {HTMLElement} view - What it scrolls.
   *
   * A bar with nothing to scroll keeps its trough and loses its knob and its
   * arrows, which is what the original shows: the trough is part of the view
   * rather than a thing that appears when it is needed.
   */
  fit({ trough, knob, arrows, how }, view) {
    const more = this.holdsMore(how, view);
    knob.hidden = !more;
    arrows.hidden = !more;
    if (!more) return;

    const overflow = view[how.length] - view[how.showing];
    const room = trough[how.room];
    const size = Math.max(NxScroller.SMALLEST_KNOB,
                          room * view[how.showing] / view[how.length]);
    knob.style[how.size] = size + "px";
    knob.style[how.edge] = (view[how.along] / overflow) * (room - size) + "px";
  }

  /**
   * Whether the view hides anything a reader could scroll to.
   * @param {WayParts} how - One of WAYS.
   * @param {HTMLElement} view - What scrolls.
   * @returns {boolean}
   *
   * The two figures cannot be compared as they come. Both are whole pixels
   * rounded from sizes that are fractions wherever the desk is drawn at 125,
   * 150 or 175 per cent, and WebKit then reports the content one pixel longer
   * than a view it fits in: a File Viewer path that fills its band exactly,
   * and a folder far shorter than its band. And the padding at the far end is
   * room rather than content, so a band the window leaves a few pixels short
   * of it still shows everything in it. So what counts is how far the content
   * runs past that padding, and only by more than one rounding.
   */
  holdsMore(how, view) {
    const trailing = parseFloat(getComputedStyle(view)[how.trailing]) || 0;
    const past = view[how.length] - view[how.showing] - trailing;
    return past > NxScroller.ROUNDING;
  }
}
NxScroller.LINE = 18;            /* how far one press of an arrow moves the view */
NxScroller.SMALLEST_KNOB = 16;   /* below this the knob is no longer a target */
NxScroller.ROUNDING = 1;         /* what two sizes rounded to whole pixels can differ by */

/* --- nx-shelf and nx-thing ---------------------------------------------- */

/** A floor of icons, of which at most one is chosen at a time. */
class NxShelf extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;
    this.addEventListener("click", (event) => {
      const thing = closestTo(event, "nx-thing");
      if (!thing || !this.contains(thing)) return;
      if (thing.hasAttribute("disabled")) return;
      this.choose(thing);
    });
  }

  /** @param {HTMLElement} thing - The one to mark, clearing the others. */
  choose(thing) {
    for (const other of this.querySelectorAll("nx-thing")) other.removeAttribute("chosen");
    thing.setAttribute("chosen", "");
  }
}

/**
 * One thing on a shelf: a picture with a name under it.
 * @attr icon - Which picture it carries.
 * @attr label - The name under it.
 * @attr chosen - Draw it selected.
 */
class NxThing extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    const slot = document.createElement("span");
    slot.className = "slot art";
    const art = document.createElement("i");
    art.className = "art icon";
    showArt(art, this.getAttribute("icon") ?? "");
    slot.append(art);

    const name = document.createElement("span");
    name.className = "name";
    name.textContent = this.getAttribute("label") ?? "";

    this.append(slot, name);
    this.art = art;

    if (this.hasAttribute("value")) this.carry();
    this.draggable = this.canBeUsed;
  }

  /** Watched so that switching a thing off takes its drag handle with it. */
  static get observedAttributes() { return ["disabled"]; }

  attributeChangedCallback() {
    if (this.ready) this.draggable = this.canBeUsed;
  }

  /** @returns {string} What this thing hands over when it is used, which is
   *  "" for a thing that hands nothing over. */
  get value() { return this.getAttribute("value") ?? ""; }

  /** @returns {boolean} Whether it hands anything over at all. A thing can be
   *  switched off because using it would do nothing, which is different from
   *  having nothing to give. */
  get canBeUsed() {
    return this.hasAttribute("value") && !this.hasAttribute("disabled");
  }

  /**
   * Makes it liftable, and makes a double click mean the same as carrying it
   * somewhere and letting go.
   *
   * Both raise `nx-choose`, which bubbles, so a page answers in one place
   * however the thing was used.
   */
  carry() {
    this.addEventListener("dragstart", (event) => {
      /* Checked here rather than when this was wired, because a thing is
         switched off and on again while the page is up. */
      if (!this.canBeUsed || !event.dataTransfer) return event.preventDefault();
      event.dataTransfer.setData("text/plain", this.value);
      event.dataTransfer.effectAllowed = "copy";
      this.setAttribute("lifting", "");
    });

    this.addEventListener("dragend", () => this.removeAttribute("lifting"));

    this.addEventListener("dblclick", () => {
      if (!this.canBeUsed) return;
      this.dispatchEvent(new CustomEvent("nx-choose", {
        bubbles: true, detail: { value: this.value },
      }));
    });
  }

  /** @param {string} icon - Swap the picture without rebuilding the thing. */
  set icon(icon) {
    this.setAttribute("icon", icon);
    if (this.art) showArt(this.art, icon);
  }
}

/* --- nx-ask ------------------------------------------------------------- */

/**
 * What a panel asks, says and offers.
 * @typedef {object} Question
 * @property {string} name - What the panel calls itself, after the command
 *   that brought it up. It stands beside the icon above the groove, because
 *   an attention panel's title bar is empty.
 * @property {string} [subtitle] - A line under the name, above the groove, in
 *   the panel's ordinary type. Left out, the name stands alone.
 * @property {(string | Node)[]} text - One paragraph per entry, below the
 *   groove, as a sentence or as an element where the caller had to build the
 *   line itself.
 * @property {string} [icon] - Which picture, by the name showArt knows.
 * @property {string} confirm - The wording on the acting button. The kit holds
 *   no words of its own, in any language, so both buttons are named by
 *   whoever asks.
 * @property {string | null} [cancel] - The wording on the safe one. Left out,
 *   the panel has one button.
 * @property {boolean} [field] - Show a line to type into.
 * @property {boolean} [secret] - Draw that line as a password field, so what
 *   is typed into it is not read over the typist's shoulder.
 * @property {boolean} [dangerous] - Whether the acting button costs something
 *   that does not come back. Such a button takes no Return and carries no
 *   Return-key symbol, so it has to be clicked. The chapter puts it the other
 *   way round, in "The default button in an attention panel should normally
 *   be operable by pressing the Return key... However, if the button has
 *   dangerous side effects, it's acceptable to require that the user press
 *   the button", so normal here is that Return presses.
 */

/**
 * The parts of the panel it writes into.
 * @typedef {object} AskParts
 * @property {HTMLElement} name - The panel's name beside the icon.
 * @property {HTMLElement} subtitle - The line under the name.
 * @property {HTMLElement} lines - The paragraphs below the groove.
 * @property {HTMLElement} icon - The picture.
 * @property {HTMLInputElement} entry - The line to type into.
 * @property {HTMLButtonElement} acting - The button that does it.
 * @property {HTMLButtonElement} safe - The button that does not.
 */

/**
 * The panel that asks before anything changes.
 *
 * NeXTSTEP's attention panel comes up in the upper part of the screen with the
 * icon of whatever is about to happen, a sentence saying what it is, and the
 * safe answer on the left. This is that, and it is a component rather than
 * markup in the page because more than one thing needs to ask: stopping the
 * emulator does, and changing the machine does.
 *
 * Its title bar is empty, which is what tells an attention panel from an
 * ordinary one. The panel is named inside itself, beside the icon, after
 * whatever brought it up, so the first line a caller gives is that name.
 *
 * It answers with a promise rather than a callback, so the caller reads as one
 * sequence: ask, then act on the answer.
 */
class NxAsk extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    /* Two blocks with a groove between them, which is how the chapter's own
       figure of an attention panel is built: the application icon and the
       panel's name above the line, and what the panel has to say below it. */
    this.innerHTML = `
      <div class="panel">
        <div class="titlebar"></div>
        <div class="naming">
          <i class="art icon raised"></i>
          <div class="heading">
            <div class="name"></div>
            <p class="subtitle" hidden></p>
          </div>
        </div>
        <div class="pane">
          <div class="lines"></div>
          <input class="entry sunken" type="text" spellcheck="false" hidden>
          <div class="buttons" style="padding-right:0">
            <button data-answer="no"></button>
            <button data-answer="yes"></button>
          </div>
        </div>
      </div>`;

    /** @type {AskParts} The parts the panel writes into, found once. */
    this.parts = {
      name: this.ownPart(".name", HTMLElement),
      subtitle: this.ownPart(".subtitle", HTMLElement),
      lines: this.ownPart(".lines", HTMLElement),
      icon: this.ownPart(".icon", HTMLElement),
      entry: this.ownPart(".entry", HTMLInputElement),
      acting: this.ownPart('[data-answer="yes"]', HTMLButtonElement),
      safe: this.ownPart('[data-answer="no"]', HTMLButtonElement),
    };

    /** @type {((answer: boolean) => void) | null} */
    this.settle = null;
    this.returns = true;
    for (const button of [this.parts.safe, this.parts.acting]) {
      button.addEventListener("click", () => this.close(button.dataset.answer === "yes"));
    }

    /* Escape is the safe answer, which is the one a panel like this must have:
       somebody who wants out of a question should not have to aim at a button.

       Return presses the acting button, and only that one: "No button except
       for the default button should be operable by the Return key." Where the
       panel said its default is dangerous, Return presses nothing at all and
       the answer has to be clicked. */
    /** @type {(event: KeyboardEvent) => void} */
    this.keys = (event) => {
      if (event.key === "Escape") this.close(false);
      if (event.key === "Enter" && this.returns) this.close(true);
    };

    /* The mark says Return will press the button, so it has to stop saying so
       the moment Return would not. In a browser that is the document losing
       focus, which is this desk's version of the panel not being the key
       window. */
    /** @type {() => void} */
    this.focusChanged = () => this.markTheReturnKey();
  }

  /**
   * One part of the panel's own markup.
   * @template {Element} Kind
   * @param {string} selector - Where it is.
   * @param {new () => Kind} kind - What it is.
   * @returns {Kind}
   *
   * The markup is the panel's own, written a few lines above, so a part that
   * is missing or of another kind is a mistake in this file and says so at once
   * rather than as a null somewhere later.
   */
  ownPart(selector, kind) {
    const found = this.querySelector(selector);
    if (!(found instanceof kind)) throw new Error(`nx-ask has no ${selector}`);
    return found;
  }

  /**
   * Puts the question and waits for an answer.
   * @param {Question} question
   * @returns {Promise<boolean>} True where the acting button was pressed.
   */
  ask({ name, subtitle, text, icon, confirm, cancel, field = false,
        secret = false, dangerous = false }) {
    const parts = this.parts;
    parts.name.textContent = name;
    parts.subtitle.hidden = !subtitle;
    parts.subtitle.textContent = subtitle ?? "";
    parts.lines.replaceChildren(
      ...text.map((line) => {
        /* A line is a sentence, or an element where the caller had to build
           it: a copyright carrying a link is still one line, and the kit has
           no business knowing which word in it leads where. */
        if (line instanceof Node) return line;
        const paragraph = document.createElement("p");
        paragraph.textContent = line;
        return paragraph;
      }));
    if (icon) showArt(parts.icon, icon);

    const acting = parts.acting;
    acting.textContent = confirm;

    /* A panel that only says something has one button, and the safe answer is
       the same as the acting one. Left standing and empty it would be a second
       button offering nothing, which is worse than none. */
    const safe = parts.safe;
    safe.hidden = !cancel;
    safe.textContent = cancel ?? "";

    const entry = parts.entry;
    entry.hidden = !field;
    entry.type = secret ? "password" : "text";
    entry.value = "";

    this.returns = !dangerous;
    this.markTheReturnKey();

    this.toggleAttribute("data-open", true);
    addEventListener("keydown", this.keys);
    addEventListener("focus", this.focusChanged);
    addEventListener("blur", this.focusChanged);
    (field ? entry : (cancel ? safe : acting)).focus();

    return new Promise((settle) => { this.settle = settle; });
  }

  /** Puts the Return-key symbol on the acting button, or takes it off. */
  markTheReturnKey() {
    this.parts.acting.classList.toggle("returns", this.returns && document.hasFocus());
  }

  /**
   * Says something and waits for it to be read.
   * @param {Pick<Question, "name" | "subtitle" | "text" | "icon" | "confirm">} panel
   *   What it says, as ask takes it, with the one button's wording.
   * @returns {Promise<boolean>} Always true, so the caller can wait for it to
   *   be dismissed without reading the answer.
   *
   * The whole of it is ask with no safe button, because a panel that only says
   * something has one answer and offering a second would be a button that does
   * what the first does.
   */
  tell({ name, subtitle, text, icon, confirm }) {
    return this.ask({ name, subtitle, text, icon, confirm, cancel: null });
  }

  /**
   * Puts a question that needs something typed.
   * @param {Question} question - As ask, and the field is shown.
   * @returns {Promise<string|null>} What was typed, or null where the panel was
   *   dismissed. Empty counts as dismissed, because a blank answer is not one.
   */
  async askFor(question) {
    const answered = await this.ask({ ...question, field: true });
    if (!answered) return null;
    const typed = this.parts.entry.value.trim();
    return typed || null;
  }

  /**
   * Closes the panel and settles whoever was waiting.
   * @param {boolean} answer
   */
  close(answer) {
    this.toggleAttribute("data-open", false);
    removeEventListener("keydown", this.keys);
    removeEventListener("focus", this.focusChanged);
    removeEventListener("blur", this.focusChanged);
    this.settle?.(answer);
    this.settle = null;
  }
}

/* --- nx-viewer ---------------------------------------------------------- */

/**
 * One icon in the viewer: a step of the path, a thing in the contents, or one
 * kept on the shelf.
 * @typedef {object} ViewerEntry
 * @property {string} [label] - The name under it.
 * @property {string} [icon] - Which picture, by the name showArt knows.
 * @property {string} [value] - What choosing it hands over. Left out, it hands
 *   nothing over.
 * @property {boolean} [folder] - In the contents, that it has more inside.
 */

/**
 * NeXTSTEP's File Viewer, which is four bands stacked in one window.
 *
 * The shelf along the top keeps whatever is dropped on it and has nothing to
 * do with where you are. Under it one line of status about the whole. Then the
 * path, as a row of icons with an arrow between each pair. Then what the last
 * step of that path holds, in a scroller.
 *
 * It knows nothing about what it is showing. The page hands it a path and a
 * list of contents and listens for what was chosen, so the same component
 * serves machines, a shared directory, or anything else that is a place with
 * things in it.
 *
 * @attr status - The line under the shelf, where the page has nothing more
 *   particular to say.
 * @fires nx-path - A step of the path was chosen, carrying its index in
 *   `detail.index` and its value in `detail.value`.
 * @fires nx-visit - Something on the shelf was clicked once, carrying its
 *   value. One click there is an act rather than a selection.
 * @fires nx-choose - Something in the contents or on the shelf was chosen,
 *   from nx-thing, carrying its value.
 */
class NxViewer extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    /** @type {NxShelf} */
    this.keep = document.createElement("nx-shelf");
    this.keep.className = "keep";

    /* One click on the shelf is an act, which is the one place in this viewer
       where that is true: NeXT's guidelines say that clicking a folder there
       changes what the viewer shows, and that a drag must not do the same,
       which is why the shelf is the example they use for it. */
    this.keep.addEventListener("click", (event) => {
      const thing = closestTo(event, "nx-thing");
      if (!thing || !this.keep.contains(thing)) return;
      /* Raised on the thing rather than on the viewer, so that whoever
         answers knows which icon was clicked and not merely that one was.
         An icon that travels has to start where it is. */
      thing.dispatchEvent(new CustomEvent("nx-visit", {
        bubbles: true,
        detail: { value: thing.getAttribute("value") },
      }));
    });
    this.keep.addEventListener("dragover", (event) => {
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = "copy";
      this.keep.setAttribute("droppable", "");
    });
    this.keep.addEventListener("dragleave", (event) => {
      const into = event.relatedTarget;
      if (!(into instanceof Node && this.keep.contains(into))) {
        this.keep.removeAttribute("droppable");
      }
    });
    this.keep.addEventListener("drop", (event) => {
      event.preventDefault();
      this.keep.removeAttribute("droppable");
      this.dispatchEvent(new CustomEvent("nx-keep", {
        bubbles: true,
        detail: { value: event.dataTransfer?.getData("text/plain") ?? "" },
      }));
    });

    /** @type {HTMLParagraphElement} */
    this.status = document.createElement("p");
    this.status.className = "status";
    this.status.textContent = this.getAttribute("status") ?? "";

    /** @type {HTMLDivElement} */
    this.path = document.createElement("div");
    this.path.className = "path";
    this.path.addEventListener("click", (event) => {
      const thing = closestTo(event, "nx-thing");
      if (!thing || !this.path.contains(thing)) return;
      this.dispatchEvent(new CustomEvent("nx-path", {
        bubbles: true,
        detail: { index: Number(thing.dataset.step), value: thing.getAttribute("value") },
      }));
    });

    /* The path is a browser in the original and scrolls sideways as it grows,
       with its trough under it whether there is anything to scroll or not. */
    const way = document.createElement("nx-scroller");
    way.setAttribute("bars", "across");
    way.className = "way";
    way.append(this.path);

    /** @type {NxShelf} */
    this.contents = document.createElement("nx-shelf");
    this.contents.className = "contents";
    const scroller = document.createElement("nx-scroller");
    scroller.setAttribute("bars", "down across");
    scroller.append(this.contents);

    this.append(this.keep, this.status, way, scroller);
  }

  /**
   * Puts a place and its contents in the window.
   * @param {object} view
   * @param {ViewerEntry[]} [view.path] - The way here, outermost first.
   * @param {ViewerEntry[]} [view.contents] - What the last step holds.
   * @param {ViewerEntry[]} [view.keeps] - What lies on the shelf. Left out,
   *   the shelf is not touched.
   * @param {string} [view.status] - The line under the shelf.
   */
  show({ path = [], contents = [], keeps, status }) {
    if (status !== undefined) this.status.textContent = status;
    if (keeps !== undefined) {
      this.keep.replaceChildren(...keeps.map((entry) => this.thing(entry)));
    }

    this.path.replaceChildren(...path.flatMap((step, index) => {
      const thing = this.thing(step);
      thing.dataset.step = String(index);
      /* The last step is where you are, and the shape that says so is the one
         a chosen thing already wears. */
      if (index === path.length - 1) thing.setAttribute("chosen", "");
      if (index === 0) return [thing];
      return [this.arrow(), thing];
    }));

    this.contents.replaceChildren(...contents.map((entry) => {
      const thing = this.thing(entry);
      if (entry.folder) thing.setAttribute("folder", "");
      return thing;
    }));
  }

  /**
   * @param {ViewerEntry} entry - What to draw.
   * @returns {NxThing} The icon with its name, ready to be appended.
   */
  thing(entry) {
    const thing = document.createElement("nx-thing");
    thing.setAttribute("icon", entry.icon ?? "");
    thing.setAttribute("label", entry.label ?? "");
    if (entry.value !== undefined) thing.setAttribute("value", entry.value);
    return thing;
  }

  /** @returns {HTMLElement} The mark between two steps of the path. */
  arrow() {
    const arrow = document.createElement("i");
    arrow.className = "step-arrow";
    return arrow;
  }
}

/* --- nx-slider ----------------------------------------------------------- */

/** What a step stands for, as whoever uses the slider counts it.
 *  @typedef {string | number} SliderValue */

/**
 * One step on the scale.
 * @typedef {object} SliderStep
 * @property {SliderValue} value - What landing on it hands back.
 * @property {string} label - What it is called, read out to assistive
 *   technology.
 * @property {string} [tick] - What stands over it on the scale, which is the
 *   figure alone.
 */

/**
 * A knob in a trough, moving between the steps it is given.
 *
 * It holds no scale of its own: whatever uses it hands over the steps and what
 * each is called, and hears back which one was landed on. So a slider here says
 * nothing about megahertz or megabytes, and the words stay with whoever owns
 * them.
 *
 * @attr dragging - Set while the knob follows the pointer, which is what takes
 *   the travel off it so it does not trail behind the hand.
 * @attr fixed - Set where there is only one step, so the control reads as a
 *   statement rather than as a choice.
 * @fires nx-slide - `{ value }` of the step landed on, whenever that changes.
 */
class NxSlider extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    /** @type {HTMLDivElement} */
    this.trough = document.createElement("div");
    this.trough.className = "trough";
    /** @type {HTMLDivElement} */
    this.knob = document.createElement("div");
    this.knob.className = "knob";
    this.trough.append(this.knob);

    /* The ticks stand over the trough, each above the place its step puts the
       knob, so the scale is read before the hand reaches it rather than from
       under the hand that is on it. */
    /** @type {HTMLDivElement} */
    this.ticks = document.createElement("div");
    this.ticks.className = "ticks";

    const scale = document.createElement("div");
    scale.className = "scale";
    scale.append(this.ticks, this.trough);

    /* The unit, once, to the left of the scale. The ticks carry figures alone
       and the one in force is the black one, so the unit is the only thing left
       to say and saying it beside every tick would crowd them out. */
    /** @type {HTMLSpanElement} */
    this.unit = document.createElement("span");
    this.unit.className = "unit";

    this.append(this.unit, scale);
    /** @type {SliderStep[]} */
    this.steps = [];

    this.tabIndex = 0;
    this.setAttribute("role", "slider");
    this.wire();
  }

  /** @param {string} unit - What the figures on this scale are counted in,
   *  such as MHz or MB. Stated once, to the left of the scale. */
  set says(unit) {
    this.unit.textContent = unit;
  }

  /**
   * The steps this slider offers.
   * @param {SliderStep[]} steps - In the order they sit on the scale. A tick
   *   is the figure alone: the unit stands once to the left of the scale, and
   *   five of them along one trough would not fit.
   *
   * Set every time the answer changes, because which steps exist depends on the
   * machine: a clock gains one with a turbo board, and memory loses two without
   * it.
   */
  set options(steps) {
    this.steps = steps;
    this.toggleAttribute("fixed", steps.length < 2);
    this.setAttribute("aria-valuemin", "0");
    this.setAttribute("aria-valuemax", String(Math.max(steps.length - 1, 0)));
    this.drawTheTicks();
    this.draw();
  }

  /** Puts one tick under each step, where that step puts the knob.
   *
   *  A scale of one step draws none, because there is nothing to choose
   *  between and a lone tick would read as a mark somebody could aim at. */
  drawTheTicks() {
    const last = Math.max(this.steps.length - 1, 1);
    this.ticks.replaceChildren(...(this.steps.length < 2 ? [] :
      this.steps.map((step, at) => {
        const tick = document.createElement("span");
        tick.className = "tick";
        tick.textContent = step.tick ?? "";
        /* Under the middle of the knob when it stands on this step, which is
           half a knob in plus that step's share of the room it travels. */
        tick.style.left =
          `calc(var(--knob-width) / 2 + (100% - var(--knob-width)) * ${at / last})`;
        return tick;
      })));
  }

  /** @returns {SliderValue | undefined} The value of the step the knob is on,
   *  or nothing before one has been chosen. */
  get value() {
    return this.at === undefined ? undefined : this.steps[this.at]?.value;
  }

  /** @param {SliderValue | undefined} value - Which step to stand on. One that
   *  is not a step leaves the knob at the start, which is what a machine that
   *  has just changed answers with. */
  set value(value) {
    const found = this.steps.findIndex((step) => step.value === value);
    /** @type {number | undefined} Which step the knob is on, from 0, once one
     *  has been chosen. */
    this.at = found < 0 ? 0 : found;
    this.draw();
  }

  /** Puts the knob where its step is and says what that step is called. */
  draw() {
    const at = this.at ?? 0;
    const last = Math.max(this.steps.length - 1, 1);
    /* In per cent of the room the knob has to travel, which is the trough less
       the knob itself. Stated that way rather than in pixels, so it is right
       before the trough has been laid out and stays right when it changes
       width. */
    this.knob.style.transform =
      `translateX(calc((100cqw - var(--knob-width)) * ${at / last}))`;
    this.setAttribute("aria-valuenow", String(at));
    this.setAttribute("aria-valuetext", this.steps[at]?.label ?? "");

    /* Which tick is in force, so the scale says where the knob stands as well
       as the knob does. */
    for (const [index, tick] of [...this.ticks.children].entries()) {
      tick.toggleAttribute("chosen", index === at);
    }
  }

  /** Listens for the pointer on the trough and for the arrow keys. */
  wire() {
    this.trough.addEventListener("pointerdown", (event) => {
      if (this.hasAttribute("fixed")) return;
      this.setAttribute("dragging", "");
      this.trough.setPointerCapture(event.pointerId);
      this.reachFor(event);
    });

    this.trough.addEventListener("pointermove", (event) => {
      if (this.hasAttribute("dragging")) this.reachFor(event);
    });

    for (const ending of ["pointerup", "pointercancel"]) {
      this.trough.addEventListener(ending, () => this.removeAttribute("dragging"));
    }

    this.addEventListener("keydown", (event) => {
      const by = { ArrowLeft: -1, ArrowDown: -1, ArrowRight: 1, ArrowUp: 1 }[event.key];
      if (by === undefined || this.hasAttribute("fixed")) return;
      event.preventDefault();
      this.land((this.at ?? 0) + by);
    });
  }

  /**
   * Lands on the step nearest where the pointer is.
   * @param {PointerEvent} event
   */
  reachFor(event) {
    const trough = this.trough.getBoundingClientRect();
    const knob = this.knob.getBoundingClientRect();
    /* Measured from the middle of the knob, so the step under the pointer is
       the one it looks like rather than the one half a knob to its left. */
    const along = event.clientX - trough.left - knob.width / 2;
    const room = trough.width - knob.width;
    const last = Math.max(this.steps.length - 1, 1);
    this.land(Math.round((along / (room || 1)) * last));
  }

  /**
   * Stands on one step, where that is a step at all.
   * @param {number} at - Which of them, from 0.
   */
  land(at) {
    const wanted = Math.min(Math.max(at, 0), this.steps.length - 1);
    if (wanted === this.at) return;
    this.at = wanted;
    this.draw();
    this.dispatchEvent(new CustomEvent("nx-slide", {
      bubbles: true, detail: { value: this.value },
    }));
  }
}

/* --- nx-leds ------------------------------------------------------------- */

/** How many lamps a row has where it does not say. Twenty is one lamp for
 *  every five per cent, which is as fine as an eye reads a row of lamps at a
 *  glance and still fits beside a label in a panel. */
const LEDS_IN_A_ROW = 20;

/**
 * A row of lamps lighting from the left, for a share of something.
 *
 * It holds no scale beyond the share itself: whoever uses it hands over a
 * percentage and the words for it, and the words stay with whoever owns them.
 * It is drawn once for each value it is given and never animated, because a
 * lamp has no state between on and off.
 *
 * @attr lamps - How many lamps the row has. LEDS_IN_A_ROW where it does not
 *   say.
 */
class NxLeds extends HTMLElement {
  connectedCallback() {
    if (this.ready) return;
    this.ready = true;

    this.row = document.createElement("div");
    this.row.className = "lamps";
    const count = Number(this.getAttribute("lamps")) || LEDS_IN_A_ROW;
    for (let lamp = 0; lamp < count; lamp += 1) {
      const led = document.createElement("i");
      led.className = "led";
      this.row.append(led);
    }

    /* Beside the row rather than over it, the way the unit stands beside a
       slider, so the lamps are never covered by what they mean. */
    this.figure = document.createElement("span");
    this.figure.className = "says";
    this.figure.textContent = this.words ?? "";

    this.append(this.row, this.figure);
    this.setAttribute("role", "meter");
    this.setAttribute("aria-valuemin", "0");
    this.setAttribute("aria-valuemax", "100");
    this.draw();
  }

  /** @returns {number|null} The share last given, in per cent. */
  get value() {
    return this.share ?? null;
  }

  /**
   * @param {number|null} percent - How full whatever it measures is, from 0
   *   to 100. Anything outside that lights all of the row or none of it, and
   *   null is a reading that is not there, which lights nothing.
   *
   * Kept even before the row is on the page, and drawn once it arrives, so
   * whoever builds one can fill it in before or after putting it somewhere.
   */
  set value(percent) {
    this.share = Number.isFinite(percent) ? percent : null;
    this.draw();
  }

  /** @param {string} words - What the share is, in the words of whoever
   *  measures it, such as `12 %`. Written beside the row. */
  set says(words) {
    this.words = words;
    if (this.figure) this.figure.textContent = words;
    this.setAttribute("aria-valuetext", words);
  }

  /** Lights as many lamps from the left as the share is of the row.
   *
   *  Rounded to the nearest lamp, so a row of twenty lights its first lamp at
   *  two and a half per cent and its last at ninety-seven and a half. */
  draw() {
    if (!this.row) return;
    const lamps = [...this.row.children];
    const share = this.value === null ? null : Math.min(Math.max(this.value, 0), 100);
    const lit = share === null ? 0 : Math.round(share / 100 * lamps.length);
    for (const [index, lamp] of lamps.entries()) {
      lamp.toggleAttribute("lit", index < lit);
    }

    if (share === null) this.removeAttribute("aria-valuenow");
    else this.setAttribute("aria-valuenow", String(share));
  }
}

/**
 * Defines every element the kit brings, and picks the front window.
 *
 * Called rather than done at import, so that whoever imports this
 * has put the words on the page before the first element is built.
 */
export function defineTheKit() {
  /** @type {[string, CustomElementConstructor][]} */
  const elements = [
  ["nx-window", NxWindow],
  ["nx-menu", NxMenu],
  ["nx-menu-item", NxMenuItem],
  ["nx-popup", NxPopup],
  ["nx-dock", NxDock],
  ["nx-tile", NxTile],
  ["nx-floor", NxFloor],
  ["nx-scroller", NxScroller],
  ["nx-shelf", NxShelf],
  ["nx-thing", NxThing],
  ["nx-ask", NxAsk],
  ["nx-viewer", NxViewer],
  ["nx-slider", NxSlider],
  ["nx-leds", NxLeds],
  ];
  for (const [tag, type] of elements) {
    customElements.define(tag, type);
  }

  /* After the definitions, because every window has to exist and
     know whether it is open before one of them can be picked out as
     the front one. */
  restoreFront();
}

