  LEDS_IN_A_ROW,
  NEAR_FLIGHT_MS,
  NxAsk,
  NxDock,
  NxFloor,
  NxLeds,
  NxMenu,
  NxMenuItem,
  NxPopup,
  NxScroller,
  NxShelf,
  NxSlider,
  NxThing,
  NxTile,
  NxViewer,
  NxWindow,
  STORE,
  SVG_NS,
  WAYS,
  ZOOM_MS,
  ZOOM_RECTANGLES,
  between,
